; moire.asm -- chapter 13: a picture of multiplication
; generated by gen13.py
        INCLUDE "msx.inc"
        OUTPUT "moire.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
SQ      EQU $D000               ; the table of quarter squares
acc     EQU VARS               ; the byte being built, eight pixels
; A picture of multiplication: for every pixel, a across (0 to 255) and e
; down (0 to 191), bit 9 of a x e worked out by mul, 1 for ink (figure
; 13.3). The bytes go to the VDP in the order of Graphic II's patterns: a
; cell's eight lines, then the next cell. mul uses A, BC, DE and HL: the
; halves of IY and IX count.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        call sqinit
        VRAM_WRITE $0000        ; the patterns, from the first
        ld iyh, 0               ; the cell's top line: 0, 8 ... 184
mo1:    ld iyl, 0               ; the cell's left column: 0, 8 ... 248
mo2:    ld ixh, 0               ; the line in the cell: 0 to 7
mo3:    ld ixl, 0               ; the pixel in the line: 0 to 7
mo4:    ld a, iyh
        add a, ixh
        ld e, a                 ; e: the pixel's line
        ld a, iyl
        add a, ixl              ; a: its column
        call mul                ; HL = a x e
        ld a, h
        rra
        rra                     ; bit 9 of the product into the carry
        ld hl, acc
        rl (hl)                 ; and in at the right of the byte
        inc ixl
        ld a, ixl
        cp 8
        jr nz, mo4              ; eight pixels to a byte
        ld a, (acc)
        out (VDP_DATA), a       ; the byte, to the next place in the VRAM
        inc ixh
        ld a, ixh
        cp 8
        jr nz, mo3              ; eight lines to a cell
        ld a, iyl
        add a, 8
        ld iyl, a
        jr nz, mo2              ; 32 cells across
        ld a, iyh
        add a, 8
        ld iyh, a
        cp 192
        jr nz, mo1              ; 24 rows of cells
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; mul: HL = A x E, both taken as unsigned. Uses A, BC, DE.
mul:    ld d, a
        add a, e                ; a + e: the carry is its ninth bit
        ld l, a
        ld a, high SQ
        adc a, 0                ; the page: the first or the second
        ld h, a
        ld c, (hl)              ; the low byte of (a + e)(a + e)/4
        inc h
        inc h                   ; the high bytes are two pages on
        ld b, (hl)
        ld a, d
        sub e                   ; a - e
        jr nc, mu1
        neg                     ; its size, if it was negative
mu1:    ld l, a
        ld h, high SQ           ; under 256: the first page
        ld e, (hl)
        inc h
        inc h
        ld d, (hl)              ; DE = (a - e)(a - e)/4
        ld h, b
        ld l, c
        or a                    ; the carry clear for SBC
        sbc hl, de
        ret

; sqinit: n*n/4 for n = 0 to 510, each from the one before by adding
;         (n + 1)/2, rounded down
sqinit: ld de, SQ               ; DE: where n's low byte goes
        ld hl, 0                ; HL: n*n/4, from n = 0
        ld bc, 1                ; BC: n + 1
sq1:    ld a, l
        ld (de), a
        inc d
        inc d
        ld a, h
        ld (de), a              ; the high byte, two pages on
        dec d
        dec d
        inc de
        push bc
        srl b
        rr c                    ; (n + 1)/2
        add hl, bc              ; the next quarter square
        pop bc
        inc bc
        ld a, b
        cp 2                    ; n + 1 = 512: n = 510 was the last
        jr nz, sq1
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
